import numpy as np
def update_edge_distance(edge_distance, local_opt_tour, edge_n_used):
    updated_edge_distance = edge_distance.copy()
    n = len(local_opt_tour)
    tour_arcs = set((local_opt_tour[i], local_opt_tour[(i + 1) % n]) for i in range(n))
    for u in range(n):
        for v in range(n):
            if (u, v) not in tour_arcs and u != v:
                updated_edge_distance[u, v] *= 0.9  
    return updated_edge_distance
